import base64,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
files={p.name[:-3]:base64.b64encode(p.read_bytes()).decode() for p in (ROOT/'policy_lookup').glob('*.policy.gz')}
engine='const TABLES='+json.dumps(files,separators=(',',':'))+';\n'+r'''
const decoded=new Map();
async function table(key){if(decoded.has(key))return decoded.get(key);if(!TABLES[key])throw Error('This progression state is outside the packaged lookup.');if(typeof DecompressionStream==='undefined')throw Error('This browser lacks gzip decompression. Use the Python lookup.');const bytes=Uint8Array.from(atob(TABLES[key]),c=>c.charCodeAt(0));const buf=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(decoded.size>=2)decoded.delete(decoded.keys().next().value);decoded.set(key,buf);return buf;}
function inputCount(limit,target){const d=Array(limit+1).fill(999),q=[1];d[1]=0;for(let i=0;i<q.length;i++)for(const delta of [-10,-1,1,10]){const y=Math.max(1,Math.min(limit,q[i]+delta));if(d[y]===999){d[y]=d[q[i]]+1;q.push(y);}}return d[target];}
async function choose(x){const {region,milestone,owned:F,shells:S,rupees:R,chance:b,profile,windMode}=x;for(const n of [F,S,R,b])if(!Number.isInteger(n))throw Error('Enter whole numbers.');if(F<0||F>136||S<0||S>999||R<0||R>999||b<0||b>100)throw Error('A value exceeds a game inventory limit.');if(F===136)return {action:'complete'};if(b===0)return {action:'wait',reason:'The currently eligible pool is exhausted.'};if(milestone==='full'&&b!==Math.max(1,Math.floor(100*(136-F)/136)))return {action:'wait',reason:'The base chance does not match the full 136 pool. Finish remaining eligibility unlocks, or check the inputs.'};let j={earth:0,fire:1,boots:2,mitts:3,water:4,crypt:5,wind:6,full:8}[milestone];if(milestone==='wind')j=windMode==='early'?6:7;let source=profile==='earlier'?'earlier':'reference',qs=S;if(j===6&&b===Math.max(1,Math.floor(100*(130-F)/130))&&b!==Math.max(1,Math.floor(100*(123-F)/123)))source='fusion_early';if(profile==='halfcap_reference'&&j===7){source='missed_postgame';qs=Math.max(0,S-150);}const qr=[0,4].includes(R%5)?R:R-R%5;const buf=await table(`${region}_${source}_optimal_phase${j}.policy`);const ix=(F*400000+qs*400+2*Math.floor(qr/5)+(qr%5===4?1:0))*2;const a=ix+2<=buf.byteLength?new DataView(buf).getUint16(ix,true):0;const out={certifiedCashGrid:qr===R,profile,windMode};if(!a)return {...out,action:'wait',reason:'End this gallery visit and continue playing normally.'};if(a<=100){const wager=Math.min(a,101-b,S);if(!wager)throw Error('No legal wager is available.');const h=F<50?15:F<80?12:F<110?9:6;return {...out,action:'pull',wager,probability:Math.max(h,b+wager-1),pullSeconds:20+(region==='PAL'?wager-1:inputCount(Math.min(S,101-b),wager))/15};}const maxB=region==='PAL'?3:4,price=region==='PAL'?300:200,q=(a-101)%maxB+1,n=Math.floor((a-101)/maxB),wallet=j<2?300:999;if(S+30*q>999||Math.min(wallet,R+20*n)<q*price)throw Error('This state is outside the validated transaction coverage.');return {...out,action:'restock',bundles:q,farmingPickups:n,purchased:30*q,purchaseRupees:q*price,tripSeconds:(x.atFarm?25:n?45:20)+15*q+4*n,endingRupees:Math.min(wallet,R+20*n)-q*price};}
globalThis.galleryChoose=choose;
'''
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minish Cap gallery wager helper</title><style>
:root{font-family:system-ui,sans-serif;color:#1c3026;background:#f5f4e9}body{max-width:780px;margin:40px auto;padding:0 22px}h1{font-size:28px;margin-bottom:8px}.intro{line-height:1.5;color:#47594d}.card{background:white;border:1px solid #d4ddcf;border-radius:16px;padding:22px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-size:14px;font-weight:600}input,select{box-sizing:border-box;width:100%;padding:11px;font:inherit;border:1px solid #adbda9;border-radius:7px;margin-top:7px}button{background:#246342;color:white;border:0;border-radius:8px;padding:12px 17px;font:inherit;cursor:pointer;margin:16px 8px 0 0}button.secondary{color:#246342;background:#e9f1e4}#result{font-size:20px;line-height:1.5;min-height:55px}small,.note{font-size:13px;color:#576759;line-height:1.5}summary{cursor:pointer;font-weight:600}details p{line-height:1.6}.check input{width:auto;margin-right:8px}.wide{grid-column:1/-1}@media(max-width:550px){body{margin-top:20px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style><h1>Figurine Gallery wager helper</h1><p class="intro">Use current inventory and a recognizable progression stage. No future chest contents, walkthrough position, or hidden RNG state is required.</p>
<div class="card"><div class="grid"><label>Version<select id="region"><option>PAL</option><option>NTSC-U</option></select></label><label>Policy<select id="mode"><option value="single">One fixed preset</option><option value="balanced">Balanced randomized preset</option></select></label><label class="wide">Most recent progression milestone<select id="milestone"><option value="earth">Earth Element acquired</option><option value="fire">Fire Element acquired</option><option value="boots">Two-Element sword; subsequent West Hyrule story cutscene seen</option><option value="mitts">Fortress of Winds completed (Mole Mitts held)</option><option value="water">Water Element acquired</option><option value="crypt">Royal Crypt completed</option><option value="wind">Wind Element acquired, before full cleanup</option><option value="full">All figurine eligibility requirements completed</option></select></label><label>Figurines owned<input id="owned" type="number" min="0" max="136" value="0"></label><label>Shells held<input id="shells" type="number" min="0" max="999" value="70"></label><label>Current gallery rupees<input id="rupees" type="number" min="0" max="999" value="0"></label><label>Displayed chance at a 1-shell wager (%)<input id="chance" type="number" min="0" max="100" value="100"></label></div><p class="note">Click “New gallery visit” on arrival. During the Wind-stage visit, keep the stored routine after successes and duplicates.</p><button id="calculate">Show next action</button><button class="secondary" id="visit">New gallery visit</button><button class="secondary" id="reset">New playthrough / reset preset</button><p id="session" class="note"></p></div><div class="card" aria-live="polite"><div id="result">Enter your current state, then show the next action.</div><p id="detail" class="note"></p><label class="check"><input id="farm" type="checkbox">I already start this restocking cycle at the house farm</label><p class="note">The farm toggle changes the displayed trip cost, omitting the outbound leg. Farm-entry action choices are not evaluated by this practical preset.</p></div>
<details class="card"><summary>What this helper does—and the limits of its evidence</summary><p>The fixed preset is unchanged across the tested routes and versions. Its worst tested expected-time regret is 6.45%. The balanced mode samples a preset once for the whole playthrough; keep it after duplicates. Its worst tested regret is 5.04%, narrowly outside the predeclared 5% screen. Neither result proves the best conceivable observable policy.</p><p>These tables use Fast text speed, holding B, 20-second base pulls, 300 rupees/minute, and no outside rupee income. Lookup consultation time is additional. Regional prices and controls are modeled separately. NTSC ±10 and ±1 input durations are assumed equal.</p><p>“All eligibility requirements” includes optional completionist unlocks as well as the final boss. Use your actual one-shell displayed percentage. The model assumes the earliest legal wallet upgrades: 300 before the Boots milestone, 999 afterward. Delayed upgrades and arbitrary outside rupees are outside the evaluated matrix. For cash outside residues 0/4 modulo 5, the helper chooses a feasible conservative action from a lower cash row, and explicitly marks it outside the certificate; actual transaction balances are retained.</p><p>The practical lookup uses selected action representatives. Some actions have numerically tied alternatives. The report contains the full route, timing, RNG, resource, and numerical qualifications. The reconstructed shell ledger and route opportunities are conditional inputs.</p></details>
<script>'''+engine+r'''
const el=id=>document.getElementById(id);let session={profile:'reference',windMode:null,mode:'single'};try{session=JSON.parse(localStorage.getItem('gallerySession'))||session;}catch{}el('mode').value=session.mode||'single';function save(){try{localStorage.setItem('gallerySession',JSON.stringify(session));}catch{}el('session').textContent=`Preset retained: ${session.mode==='balanced'?'balanced':'fixed'}. Wind visit routine: ${session.windMode||'not yet set'}.`;}function reset(){session.mode=el('mode').value;const u=Math.random();session.profile=session.mode==='single'?'reference':u<.0466465141507168?'reference':u<.2643348216209308?'earlier':'halfcap_reference';session.windMode=null;save();}el('mode').onchange=reset;el('reset').onclick=reset;el('milestone').onchange=()=>{session.windMode=null;save();};el('visit').onclick=()=>{session.windMode=Number(el('owned').value)<80?'early':'late';save();};el('calculate').onclick=async()=>{el('calculate').disabled=true;try{if(!session.windMode)session.windMode=Number(el('owned').value)<80?'early':'late';save();const x={region:el('region').value,milestone:el('milestone').value,owned:Number(el('owned').value),shells:Number(el('shells').value),rupees:Number(el('rupees').value),chance:Number(el('chance').value),profile:session.profile,windMode:session.windMode,atFarm:el('farm').checked};const a=await choose(x);let message,detail='';if(a.action==='complete')message='All 136 figurines collected.';else if(a.action==='wait')message=a.reason;else if(a.action==='pull'){message=`Wager ${a.wager} shell${a.wager===1?'':'s'}.`;detail=`Nominal actual success chance ${a.probability}%; pull time about ${a.pullSeconds.toFixed(1)} seconds. After the result, update figurines, shells, and rupees and check again.`;}else{message=`Buy ${a.bundles} bundle${a.bundles===1?'':'s'} (${a.purchased} shells).`;detail=(a.farmingPickups?`First collect ${a.farmingPickups} red-rupee farming pickups. `:'Use your existing rupees and go directly to the shop. ')+`Purchase cost ${a.purchaseRupees} rupees; modeled cycle ${a.tripSeconds.toFixed(1)} seconds; ending rupees ${a.endingRupees}. Excess rupees are carried forward.`;}if(a.certifiedCashGrid===false)detail+=' Cash is outside the validated grid; this suggestion is feasible but its regret is not certified.';el('result').textContent=message;el('detail').textContent=detail;}catch(e){el('result').textContent=e.message;el('detail').textContent='';}finally{el('calculate').disabled=false;}};save();
</script></html>'''
(ROOT/'gallery_helper.html').write_text(html)
(ROOT.parent/'work/funded/lookup_engine.js').write_text(engine)
print('Self-contained helper written; bytes:',len(html))
